"use strict";(self.webpackChunkimport_ean_upc_barcodes_doc=self.webpackChunkimport_ean_upc_barcodes_doc||[]).push([[354],{6426(e,t,o){o.r(t),o.d(t,{comp:()=>s,data:()=>n});var r=o(641);const a=[(0,r.Fv)('<h1 id="overview" tabindex="-1"><a class="header-anchor" href="#overview"><span>Overview</span></a></h1><p>The <strong>Import EAN UPC Barcodes for WooCommerce</strong> plugin is the complete solution for adding valid GTIN (UPC/EAN) codes to your products. Whether you need to generate free internal-use codes for your store or import real GS1-registered codes from a spreadsheet, this plugin automates the entire process.</p><h2 id="what-it-does" tabindex="-1"><a class="header-anchor" href="#what-it-does"><span>What it does</span></a></h2><p>This plugin gets a valid UPC or EAN code onto every WooCommerce product in your store — old and new — either by generating a code algorithmically, or by pulling from a pool of uploaded purchased codes.</p><p>You can configure the plugin to write these codes into WooCommerce&#39;s native fields, product SKUs, or even custom metadata fields required by third-party POS or inventory systems.</p><h2 id="key-capabilities" tabindex="-1"><a class="header-anchor" href="#key-capabilities"><span>Key Capabilities</span></a></h2><ul><li><strong>Algorithm Generation</strong>: Create structurally valid EAN-13 or UPC-A barcodes with correct modulo-10 check digits instantly.</li><li><strong>Spreadsheet Import</strong>: Upload CSV, TXT, or XLSX files containing purchased barcodes to assign them to products sequentially or by mapping them to specific product IDs.</li><li><strong>Bulk Processing</strong>: Assign codes to thousands of existing simple products and variations simultaneously using an AJAX progress bar that runs safely in the background.</li><li><strong>New Product Automation</strong>: Set-and-forget rules that automatically assign or generate a code whenever a new product is created in WooCommerce.</li></ul><blockquote><p>[!NOTE] <strong>A Note on Generated Codes</strong> Generated codes are structurally valid (they have a correct check digit) but they are <strong>not GS1-registered</strong>. You should use them internally only (for label printing, POS scanning, or stock management). If you are selling on marketplaces like Google Shopping, Amazon, or eBay, you must purchase real codes and import them using the plugin&#39;s file upload feature.</p></blockquote>',8)],i={},s=(0,o(6262).A)(i,[["render",function(e,t){return(0,r.uX)(),(0,r.CE)("div",null,a)}]]),n=JSON.parse('{"path":"/guide/overview.html","title":"Overview","lang":"en-US","frontmatter":{"title":"Overview"},"headers":[{"level":2,"title":"What it does","slug":"what-it-does","link":"#what-it-does","children":[]},{"level":2,"title":"Key Capabilities","slug":"key-capabilities","link":"#key-capabilities","children":[]}],"git":{},"filePathRelative":"guide/overview.md"}')}}]);